import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new BufferedReader(new InputStreamReader(System.in)).readLine());
        long seed = Long.parseLong(st.nextToken());
        int n = Integer.parseInt(st.nextToken());
        long k = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long area = Long.parseLong(st.nextToken());
        // Side lengths strictly increase; every value is at most 1e9, so int storage is safe.
        int[] s = new int[n];
        long value = seed;
        s[0] = (int) value;
        for (int i = 1; i < n; i++) {
            value += 1 + (k * value + b) % m;
            s[i] = (int) value;
        }
        int right = n - 1;
        long answer = 0;
        for (int left = 0; left < n; left++) {
            while (right >= 0 && (long) s[left] * s[right] > area) right--;
            if (right < 0) break;
            answer += right + 1;
        }
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var seed, n, k, b, m, area int64
	fmt.Scan(&seed, &n, &k, &b, &m, &area)
	// Side lengths strictly increase; every value fits in 32 bits.
	s := make([]uint32, n)
	value := seed
	s[0] = uint32(value)
	for i := int64(1); i < n; i++ {
		value += 1 + (k*value+b)%m
		s[i] = uint32(value)
	}
	right := n - 1
	var answer int64
	for left := int64(0); left < n; left++ {
		for right >= 0 && int64(s[left])*int64(s[right]) > area {
			right--
		}
		if right < 0 {
			break
		}
		answer += right + 1
	}
	fmt.Println(answer)
}
